//! Sample playback, one synthesised string and the shared concert room. The
//! bank is read where it is shipped, as 16-bit PCM inside the binary
//! (`bank.rs`, generated by `art/music/prepare.py`); rendering allocates
//! nothing.
//!
//! Two ways to render, one sound: [`Orchestra::frame`] is the reference, one
//! stereo frame at a time, and [`Orchestra::render`] renders a run of frames
//! voice by voice and then delay line by delay line. Every sum is taken in the
//! same order as the reference takes it, so the two agree bit for bit
//! (`a_block_is_the_frames_it_replaces`).
#![allow(
    clippy::cast_precision_loss,
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss
)] // bounded sample indices and audio amplitudes
use super::{RATE, bank};
use std::sync::OnceLock;

mod plucked;
use plucked::{Lute, STRINGS};

/// How a recording is played: held (and looped), or let ring.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum Kind {
    /// A held note: recorders, bowed strings, the chanter, the horn.
    Sus,
    /// A held bed under everything: the organ and the pipe's drones.
    Drone,
    /// A plucked string, let ring to the end of its recording.
    Pluck,
    /// A bell or a cymbal, let ring.
    Bell,
    /// A drum stroke.
    Drum,
}

/// One recording as `bank.rs` lists it.
pub(super) struct Def {
    /// Its name in `samples.json` (the tests hold the two together).
    #[cfg_attr(not(test), allow(dead_code))]
    pub name: &'static str,
    /// Mono 16-bit little-endian PCM at [`RATE`].
    pub pcm: &'static [u8],
    /// The note it sounds, measured.
    pub midi: u8,
    /// How far it sits off that note, in cents (negative is flat).
    pub cents: f32,
    /// The loop, in frames: playback jumps from the end back to the start.
    pub looped: Option<(u32, u32)>,
    /// How it is played (the tests tell a drum from a note by it).
    #[cfg_attr(not(test), allow(dead_code))]
    pub kind: Kind,
    /// Seconds to full level, unless the score says otherwise.
    pub attack: f32,
    /// Seconds to silence after the note's end, unless the score says
    /// otherwise.
    pub release: f32,
    /// The share of it sent into the room.
    pub room_send: f32,
}

/// A run of recordings of one instrument in the bank, sorted by pitch.
#[derive(Clone, Copy, Debug)]
pub(super) struct Family {
    pub first: usize,
    pub len: usize,
}

impl Family {
    /// The recording nearest to `pitch`; the lower one on a tie.
    #[must_use]
    pub(super) fn nearest(self, pitch: u8) -> usize {
        let defs = &bank::BANK[self.first..self.first + self.len];
        let mut best = 0;
        for (i, def) in defs.iter().enumerate() {
            if def.midi.abs_diff(pitch) < defs[best].midi.abs_diff(pitch) {
                best = i;
            }
        }
        self.first + best
    }
}

/// The frames over which a recording that is not looped fades out at its
/// end, so a note never stops on a click.
const TAIL: usize = 1102;

pub(super) struct Instrument {
    /// The recording as shipped, read in place.
    pcm: &'static [[u8; 2]],
    /// Where playback starts for a note at `midi`: the rate factor at its own
    /// pitch, with its cents corrected.
    tune: f64,
    midi: u8,
    /// `(start, end)`: the frame playback jumps back to, and the frame it
    /// jumps from. `pcm[end]` is `pcm[start]`, so the pair at `end - 1`
    /// reads across the seam.
    looped: Option<(usize, usize)>,
    attack: f32,
    release: f32,
    room_send: f32,
    /// A one-pole low-pass on the bright families (1.0 passes it untouched):
    /// what keeps bells, cymbals, the chanter and the bowed and plucked
    /// strings from being shrill (owner, 08.10.2026).
    tone: f32,
}

/// The low-pass a recording plays through, by its family: 0.35 is about
/// 3 kHz, 0.5 about 4.9 kHz.
fn tone_of(name: &str) -> f32 {
    const DARK: [&str; 4] = ["tambourine", "fingercymbal", "cymbal", "handbell"];
    const SOFT: [&str; 7] = [
        "chanter", "psaltery", "violin-", "violins", "longbow", "chimes", "gong",
    ];
    if DARK.iter().any(|family| name.starts_with(family)) {
        0.35
    } else if SOFT.iter().any(|family| name.starts_with(family)) {
        0.5
    } else {
        1.0
    }
}

impl Instrument {
    fn len(&self) -> usize {
        self.pcm.len()
    }

    /// One sample as a number from -1 to just under 1.
    #[inline]
    fn decode(sample: [u8; 2]) -> f32 {
        f32::from(i16::from_le_bytes(sample)) / 32768.0
    }

    /// Samples `i` and `i + 1`, the two an interpolation reads, behind one
    /// bounds check.
    #[inline]
    fn pair(&self, i: usize) -> (f32, f32) {
        let [a, b] = self.pcm[i..i + 2] else {
            unreachable!("a two-sample range is two samples")
        };
        (Self::decode(a), Self::decode(b))
    }

    /// The rate a note at `pitch` reads this recording at.
    fn rate(&self, pitch: u8) -> f64 {
        self.tune * 2.0_f64.powf((f64::from(pitch) - f64::from(self.midi)) / 12.0)
    }
}

/// The bank, decoded once into its playing form.
pub(super) fn instruments() -> &'static [Instrument] {
    static BANK: OnceLock<Vec<Instrument>> = OnceLock::new();
    BANK.get_or_init(|| {
        bank::BANK
            .iter()
            .map(|def| Instrument {
                pcm: def.pcm.as_chunks::<2>().0,
                // A sample that is `cents` flat is read that much faster.
                tune: 2.0_f64.powf(-f64::from(def.cents) / 1200.0),
                midi: def.midi,
                looped: def.looped.map(|(a, b)| (a as usize, b as usize)),
                attack: def.attack,
                release: def.release,
                room_send: def.room_send,
                tone: tone_of(def.name),
            })
            .collect()
    })
}

/// How a note is touched beyond its pitch, length and level.
#[derive(Clone, Copy, Debug)]
pub(super) struct Touch {
    /// Left -1 to right 1.
    pub pan: f32,
    /// Seconds to full level; `None` takes the recording's own.
    pub attack: Option<f32>,
    /// Seconds to silence after the end; `None` takes the recording's own.
    pub release: Option<f32>,
    /// Seconds after the tick it is asked on that it begins: heterophony's
    /// breath, an ornament's place.
    pub late: f32,
}

impl Touch {
    pub(super) const fn at(pan: f32) -> Self {
        Self {
            pan,
            attack: None,
            release: None,
            late: 0.0,
        }
    }
    pub(super) const fn attack(mut self, seconds: f32) -> Self {
        self.attack = Some(seconds);
        self
    }
    pub(super) const fn release(mut self, seconds: f32) -> Self {
        self.release = Some(seconds);
        self
    }
    pub(super) const fn late(mut self, seconds: f32) -> Self {
        self.late += seconds;
        self
    }
}

struct Voice {
    instrument: usize,
    /// Frames of silence before it begins.
    wait: u32,
    /// What [`Orchestra::release`] lets go by; 0 is nothing.
    tag: u8,
    position: f64,
    rate: f64,
    age: u32,
    hold: u32,
    release: u32,
    attack: u32,
    gain: [f32; 2],
    room_send: f32,
    /// The tone filter's memory.
    low: f32,
}

impl Voice {
    /// The interpolated sample through the recording's tone filter.
    #[inline]
    fn toned(&mut self, samples: &Instrument, wave: f32) -> f32 {
        if samples.tone < 1.0 {
            self.low += (wave - self.low) * samples.tone;
            self.low
        } else {
            wave
        }
    }
    /// The envelope at this age and place: attack, squared release and the
    /// fade at a recording's end.
    #[inline]
    fn envelope(&self, samples: &Instrument, i: usize) -> f32 {
        let attack = (self.age as f32 / self.attack as f32).min(1.0);
        let release =
            (1.0 - self.age.saturating_sub(self.hold) as f32 / self.release as f32).max(0.0);
        let tail = if samples.looped.is_some() {
            1.0
        } else {
            ((samples.len() - i) as f32 / TAIL as f32).min(1.0)
        };
        attack * release * release * tail
    }

    /// Whether the note has ended: past its release, or past the end of a
    /// recording that is not looped.
    #[inline]
    fn ended(&self, samples: &Instrument, i: usize) -> bool {
        self.age >= self.hold + self.release || (samples.looped.is_none() && i + 1 >= samples.len())
    }

    /// The next read position, jumping back over a loop's seam.
    #[inline]
    fn step(&mut self, samples: &Instrument) {
        self.age += 1;
        self.position += self.rate;
        if let Some((start, end)) = samples.looped
            && self.position >= end as f64
        {
            self.position -= (end - start) as f64;
        }
    }

    /// Renders this voice into a run of frames, adding to `dry` and `feed`
    /// exactly what [`Voice::next`] would have added frame by frame, and
    /// answers whether it is still sounding.
    ///
    /// The envelope's three ratios are each exactly 1.0 for most of a note
    /// (after the attack, before the release, away from a one-shot's end), so
    /// they are only multiplied in where they are not: the same numbers,
    /// without three divisions per voice per frame.
    fn render(&mut self, bank: &[Instrument], dry: &mut [[f32; 2]], feed: &mut [f32]) -> bool {
        let samples = &bank[self.instrument];
        let mut dry = dry;
        let mut feed = feed;
        if self.wait > 0 {
            let skip = (self.wait as usize).min(dry.len());
            self.wait -= skip as u32;
            dry = &mut dry[skip..];
            feed = &mut feed[skip..];
        }
        for (out, send) in dry.iter_mut().zip(feed.iter_mut()) {
            let i = self.position as usize;
            if self.ended(samples, i) {
                return false;
            }
            let fraction = self.position.fract() as f32;
            let (a, b) = samples.pair(i);
            let wave = self.toned(samples, a + (b - a) * fraction);
            let steady = self.age >= self.attack
                && self.age <= self.hold
                && (samples.looped.is_some() || samples.len() - i >= TAIL);
            let frame = if steady {
                // Each ratio is exactly 1.0 here, and so is their product:
                // `gain * wave * 1.0` is `gain * wave`.
                self.gain.map(|gain| gain * wave)
            } else {
                let envelope = self.envelope(samples, i);
                self.gain.map(|gain| gain * wave * envelope)
            };
            self.step(samples);
            out[0] += frame[0];
            out[1] += frame[1];
            *send += (frame[0] + frame[1]) * self.room_send;
        }
        true
    }

    fn next(&mut self, bank: &[Instrument]) -> Option<[f32; 2]> {
        if self.wait > 0 {
            self.wait -= 1;
            return Some([0.0; 2]);
        }
        let samples = &bank[self.instrument];
        let i = self.position as usize;
        if self.ended(samples, i) {
            return None;
        }
        let fraction = self.position.fract() as f32;
        let (a, b) = samples.pair(i);
        let wave = self.toned(samples, a + (b - a) * fraction);
        let envelope = self.envelope(samples, i);
        self.step(samples);
        Some(self.gain.map(|gain| gain * wave * envelope))
    }
}

struct Delay {
    data: Vec<f32>,
    at: usize,
    low: f32,
}
impl Delay {
    fn new(frames: usize) -> Self {
        Self {
            data: vec![0.0; frames],
            at: 0,
            low: 0.0,
        }
    }
    fn comb(&mut self, input: f32) -> f32 {
        let out = self.data[self.at];
        // Damped: a warm room, not a bright one.
        self.low += (out - self.low) * 0.24;
        self.data[self.at] = input + self.low * 0.84;
        self.step();
        out
    }
    /// The next slot, round the ring: a compare, not a division per sample.
    fn step(&mut self) {
        self.at += 1;
        if self.at == self.data.len() {
            self.at = 0;
        }
    }
    fn diffuse(&mut self, input: f32) -> f32 {
        let old = self.data[self.at];
        let out = old - input * 0.5;
        self.data[self.at] = input + out * 0.5;
        self.step();
        out
    }
}

/// The most frames one [`Orchestra::render`] call takes.
pub(super) const BLOCK: usize = 256;
/// The most sampled voices sounding at once; a note beyond it is not played.
pub(super) const POLYPHONY: usize = 112;
/// The share of the lute sent into the room.
const LUTE_ROOM: f32 = 0.15;

pub(super) struct Orchestra {
    voices: Vec<Voice>,
    lutes: [Lute; STRINGS],
    plucks: u32,
    room: [Delay; 8],
    scatter: [Delay; 4],
    /// The master's tilt: a low-pass memory per side for a gentle high shelf.
    tilt: [f32; 2],
}

/// The master's high shelf: above about 2.5 kHz the mix is 3.7 dB softer.
#[inline]
fn tilt(low: &mut f32, x: f32) -> f32 {
    *low += (x - *low) * 0.3;
    x - 0.35 * (x - *low)
}

/// The room's share of the mix.
const WET: f32 = 0.55;

impl Default for Orchestra {
    fn default() -> Self {
        instruments();
        Self {
            voices: Vec::with_capacity(POLYPHONY),
            lutes: std::array::from_fn(|_| Lute::new()),
            plucks: 0,
            room: [1499, 1877, 2137, 2593, 1559, 1931, 2203, 2683].map(Delay::new),
            scatter: [347, 113, 379, 127].map(Delay::new),
            tilt: [0.0; 2],
        }
    }
}

/// Equal-power pan of `gain`.
fn panned(gain: f32, pan: f32) -> [f32; 2] {
    [
        ((1.0 - pan) * 0.5).sqrt() * gain,
        f32::midpoint(1.0, pan).sqrt() * gain,
    ]
}

impl Orchestra {
    /// Plays recording `instrument` at `pitch` for `seconds` (then its
    /// release), at `gain`.
    pub(super) fn note(
        &mut self,
        instrument: usize,
        pitch: u8,
        seconds: f32,
        gain: f32,
        touch: Touch,
    ) {
        if self.voices.len() >= POLYPHONY {
            return;
        }
        let sample = &instruments()[instrument];
        let attack = touch.attack.unwrap_or(sample.attack);
        let release = touch.release.unwrap_or(sample.release);
        self.voices.push(Voice {
            instrument,
            wait: (touch.late.max(0.0) * RATE as f32) as u32,
            tag: 0,
            position: 0.0,
            rate: sample.rate(pitch),
            age: 0,
            hold: (seconds.max(0.0) * RATE as f32) as u32,
            release: ((release * RATE as f32) as u32).max(1),
            attack: ((attack * RATE as f32) as u32).max(1),
            room_send: sample.room_send,
            gain: panned(gain, touch.pan),
            low: 0.0,
        });
    }

    /// Holds recording `instrument` at `pitch` until [`Self::release`] lets
    /// go of `tag`.
    pub(super) fn held(&mut self, instrument: usize, pitch: u8, gain: f32, touch: Touch, tag: u8) {
        let before = self.voices.len();
        self.note(instrument, pitch, 0.0, gain, touch);
        if self.voices.len() > before
            && let Some(voice) = self.voices.last_mut()
        {
            voice.hold = u32::MAX / 2;
            voice.tag = tag;
        }
    }

    /// Lets every voice held under `tag` go into its release now.
    pub(super) fn release(&mut self, tag: u8) {
        for voice in &mut self.voices {
            if voice.tag == tag {
                voice.hold = voice.hold.min(voice.age);
                voice.tag = 0;
            }
        }
    }

    /// Plucks a lute string: the oldest gives way when all are ringing.
    pub(super) fn lute(&mut self, pitch: u8, seconds: f32, gain: f32, pan: f32, bright: f32) {
        let slot = self
            .lutes
            .iter()
            .position(|lute| !lute.sounding)
            .unwrap_or_else(|| {
                let mut oldest = 0;
                for (i, lute) in self.lutes.iter().enumerate() {
                    if lute.age > self.lutes[oldest].age {
                        oldest = i;
                    }
                }
                oldest
            });
        self.plucks = self.plucks.wrapping_add(1);
        self.lutes[slot].pluck(pitch, seconds, panned(gain, pan), bright, self.plucks);
    }

    /// How many sampled voices are sounding.
    #[cfg(test)]
    pub(super) fn voices(&self) -> usize {
        self.voices.len()
    }

    /// Renders `out.len()` frames: the same frames, bit for bit, as as many
    /// calls of [`Self::frame`] (`a_block_is_the_frames_it_replaces`).
    /// `feed` is scratch, at least as long as `out`.
    pub(super) fn render(&mut self, out: &mut [[f32; 2]], feed: &mut [f32]) {
        let feed = &mut feed[..out.len()];
        out.fill([0.0; 2]);
        feed.fill(0.0);
        let bank = instruments();
        self.voices
            .retain_mut(|voice| voice.render(bank, out, feed));
        for lute in &mut self.lutes {
            if !lute.sounding {
                continue;
            }
            for (frame, send) in out.iter_mut().zip(feed.iter_mut()) {
                let Some(string) = lute.next() else { break };
                frame[0] += string[0];
                frame[1] += string[1];
                *send += (string[0] + string[1]) * LUTE_ROOM;
            }
        }
        // The room, delay line by delay line: each frame still sums its four
        // lines per side in the reference's order, starting from zero.
        let mut wet = [[0.0f32; 2]; BLOCK];
        let wet = &mut wet[..out.len()];
        for (i, delay) in self.room.iter_mut().enumerate() {
            for (w, f) in wet.iter_mut().zip(feed.iter()) {
                w[i / 4] += delay.comb(*f) * 0.25;
            }
        }
        for (i, delay) in self.scatter.iter_mut().enumerate() {
            for w in wet.iter_mut() {
                w[i / 2] = delay.diffuse(w[i / 2]);
            }
        }
        for (frame, w) in out.iter_mut().zip(wet.iter()) {
            for i in 0..2 {
                let x = tilt(&mut self.tilt[i], frame[i] + w[i] * WET) * 1.5;
                frame[i] = x / (1.0 + x.abs());
            }
        }
    }

    /// One stereo frame: the reference [`Self::render`] is measured against.
    pub(super) fn frame(&mut self) -> [f32; 2] {
        let mut dry = [0.0; 2];
        let mut feed = 0.0;
        let bank = instruments();
        self.voices.retain_mut(|voice| {
            if let Some(frame) = voice.next(bank) {
                dry[0] += frame[0];
                dry[1] += frame[1];
                feed += (frame[0] + frame[1]) * voice.room_send;
                true
            } else {
                false
            }
        });
        for lute in &mut self.lutes {
            if let Some(string) = lute.next() {
                dry[0] += string[0];
                dry[1] += string[1];
                feed += (string[0] + string[1]) * LUTE_ROOM;
            }
        }
        let mut wet = [0.0; 2];
        for (i, delay) in self.room.iter_mut().enumerate() {
            wet[i / 4] += delay.comb(feed) * 0.25;
        }
        for (i, delay) in self.scatter.iter_mut().enumerate() {
            wet[i / 2] = delay.diffuse(wet[i / 2]);
        }
        let mut out = [0.0; 2];
        for i in 0..2 {
            let x = tilt(&mut self.tilt[i], dry[i] + wet[i] * WET) * 1.5;
            // Soft safety ceiling leaves room for UI cues; never hard clips.
            out[i] = x / (1.0 + x.abs());
        }
        out
    }
}

